import Foundation
import Testing

@testable import Decimal128TextCodec

/// The four conformance tables, over the shared `text_bid_dpd` corpus.
///
/// The vectors are read straight out of `resources/text_bid_dpd` — the
/// `decimal128-resources` submodule — and were generated by the `decimal128-c`
/// engine through its public API. That engine reaches its answers by different
/// algorithms than this codec does, so agreement is a cross-check rather than a
/// tautology.
///
///   T1 DECODE  bid → text and dpd → text          (100, noncanonical)
///   T2 ENCODE  text → bid and text → dpd          (100)
///   T3 PARSE   input text → bits, both formats    (parse, 1,061 rows)
///   T4 ERROR   malformed input text → rejection   (error, 173 rows)
///
/// Plus the cross-format assertion: for every row both encodings must render to
/// the same text. That is the strongest property the corpus encodes.
///
/// The fifth table, `canonical`, is 84,783 rows of mostly common-path volume and
/// runs as its own suite, `TestCanonicalCorpus`.
@Suite
struct TestCorpusVectors {

    /// Every row: both encodings must render to the expected text, and
    /// therefore to each other.
    static func runDecodeTable(_ rows: [CorpusRow], _ label: String) {
        for row in rows {
            let bidText = Decimal128TextCodec.bid128ToString(row.bid)
            let dpdText = Decimal128TextCodec.dpd128ToString(row.dpd)
            #expect(bidText == row.text,
                    "\(label) line \(row.lineNumber): bid \(Hex.format32(row.bid)) rendered <\(bidText)>")
            #expect(dpdText == row.text,
                    "\(label) line \(row.lineNumber): dpd \(Hex.format32(row.dpd)) rendered <\(dpdText)>")
        }
    }

    /// Round-trippable rows: the text must encode back to the same bits.
    static func runEncodeTable(_ rows: [CorpusRow], _ label: String) {
        for row in rows {
            let b = bidParse(row.text)
            #expect(b.error == nil,
                    "\(label) line \(row.lineNumber): bid rejected <\(row.text)>: \(b.error ?? "")")
            if b.error == nil {
                #expect(b.bits == row.bid,
                        "\(label) line \(row.lineNumber): bid <\(row.text)> gave \(Hex.format32(b.bits))")
            }
            let d = dpdParse(row.text)
            #expect(d.error == nil,
                    "\(label) line \(row.lineNumber): dpd rejected <\(row.text)>: \(d.error ?? "")")
            if d.error == nil {
                #expect(d.bits == row.dpd,
                        "\(label) line \(row.lineNumber): dpd <\(row.text)> gave \(Hex.format32(d.bits))")
            }
        }
    }

    @Test("T1/T2: the 100-value table decodes and re-encodes")
    func hundred() throws {
        let rows = try Corpus.load(Corpus.hundred)
        #expect(rows.count == 100)
        Self.runDecodeTable(rows, "100")
        Self.runEncodeTable(rows, "100")
    }

    /// One-way rows: both encodings decode to the text, but at least one is a
    /// bit pattern the canonical encoder would never emit, so re-encoding is
    /// deliberately not asserted.
    @Test("T1: non-canonical encodings render as their canonical spelling")
    func nonCanonical() throws {
        let rows = try Corpus.load(Corpus.nonCanonical)
        #expect(rows.count == 1267)
        Self.runDecodeTable(rows, "noncanonical")
    }

    /// The only table that reaches the rounding surface at all.
    @Test("T3: input text parses to the expected bits in both formats")
    func parse() throws {
        let rows = try Corpus.load(Corpus.parse)
        #expect(rows.count == 1061)
        for row in rows {
            let b = bidParse(row.text)
            #expect(b.error == nil, "parse line \(row.lineNumber): bid rejected <\(row.text)>: \(b.error ?? "")")
            if b.error == nil {
                #expect(b.bits == row.bid,
                        "parse line \(row.lineNumber): bid <\(row.text)> gave \(Hex.format32(b.bits))")
            }
            let d = dpdParse(row.text)
            #expect(d.error == nil, "parse line \(row.lineNumber): dpd rejected <\(row.text)>: \(d.error ?? "")")
            if d.error == nil {
                #expect(d.bits == row.dpd,
                        "parse line \(row.lineNumber): dpd <\(row.text)> gave \(Hex.format32(d.bits))")
            }
        }
    }

    /// Malformed input. Both formats must reject, must agree on the message,
    /// and must still have written the canonical positive quiet NaN — the
    /// corpus carries that pattern in its bits columns precisely so a port can
    /// assert the written value and not merely the rejection.
    ///
    @Test("T4: malformed input is rejected identically by both formats")
    func error() throws {
        let rows = try Corpus.load(Corpus.error)
        #expect(rows.count == 173)
        for row in rows {
            let b = bidParse(row.text)
            let d = dpdParse(row.text)
            #expect(b.error != nil, "error line \(row.lineNumber): bid ACCEPTED <\(row.text)>, corpus says \(row.status)")
            #expect(d.error != nil, "error line \(row.lineNumber): dpd ACCEPTED <\(row.text)>, corpus says \(row.status)")
            if b.error != nil && d.error != nil {
                #expect(b.error == d.error,
                        "error line \(row.lineNumber): the formats disagree on <\(row.text)>")
            }
            #expect(b.bits == row.bid, "error line \(row.lineNumber): bid <\(row.text)> left \(Hex.format32(b.bits))")
            #expect(d.bits == row.bid, "error line \(row.lineNumber): dpd <\(row.text)> left \(Hex.format32(d.bits))")
        }
    }

    /// The reader itself. `parse` and `error` quote their text column, and the
    /// four rows below are exactly the ones a naive comma split corrupts while
    /// still passing — a mangled malformed input fails to parse either way.
    @Test("the quoted text column survives the reader")
    func quotedColumnRoundTrips() throws {
        let rows = try Corpus.load(Corpus.error)
        let texts = Set(rows.map(\.text))
        #expect(texts.contains(""), "the empty-string row was lost")
        #expect(texts.contains(where: { $0.hasPrefix(" ") }), "a leading-space row was lost")
        #expect(texts.contains(where: { $0.hasSuffix(" ") }), "a trailing-space row was lost")
        #expect(texts.contains(where: { $0.contains(",") }), "an embedded-comma row was lost")
    }
}

/// The full canonical table: 84,783 rows, read from the same submodule as the
/// rest. It is a separate suite only because it is two orders of magnitude
/// bigger than the other four put together, not because it is optional.
@Suite
struct TestCanonicalCorpus {

    @Test("T1/T2: the 84,783-row canonical table decodes and re-encodes")
    func canonical() throws {
        let rows = try Corpus.load(Corpus.canonical)
        #expect(rows.count == 84783)
        TestCorpusVectors.runDecodeTable(rows, "canonical")
        TestCorpusVectors.runEncodeTable(rows, "canonical")
    }
}

// ---------------------------------------------------------------------------
// Hex, in the corpus column form: 32 uppercase digits, most-significant first.
// ---------------------------------------------------------------------------

enum Hex {

    /// Parse 32 hex digits, with or without a leading `0x`.
    static func parse32(_ s: String) -> UInt128? {
        var body = Substring(s)
        if body.hasPrefix("0x") || body.hasPrefix("0X") {
            body = body.dropFirst(2)
        }
        guard body.count == 32 else { return nil }
        return UInt128(body, radix: 16)
    }

    /// Render an encoding as 32 uppercase hex digits.
    static func format32(_ v: UInt128) -> String {
        let s = String(v, radix: 16, uppercase: true)
        return String(repeating: "0", count: 32 - s.count) + s
    }
}

// ---------------------------------------------------------------------------
// The shared conformance corpus.
// ---------------------------------------------------------------------------

/// One row of a `text_bid_dpd` table.
struct CorpusRow {
    let text: String
    let bid: UInt128
    let dpd: UInt128
    /// The `status` column, present only in the input-driven tables.
    let status: String
    let lineNumber: Int
}

enum Corpus {

    /// The five tables in `resources/text_bid_dpd`, and their row counts.
    ///
    /// The counts are asserted by the tests. That is not ceremony: the text
    /// column of `parse` and `error` is double-quoted with `\\` and `\"`
    /// escapes, because those tables must carry the empty string, a leading and
    /// a trailing space, an embedded comma, an embedded quote and an embedded
    /// backslash. A naive comma split silently corrupts four rows and still
    /// passes, since a mangled malformed input fails to parse either way. The
    /// row count is what catches it.
    static let hundred = "text_bid128_dpd128_100"
    static let nonCanonical = "text_bid128_dpd128_noncanonical"
    static let parse = "text_bid128_dpd128_parse"
    static let error = "text_bid128_dpd128_error"
    static let canonical = "text_bid128_dpd128_canonical"

    /// `resources/text_bid_dpd` — the decimal128-resources submodule, mounted at
    /// the repo root the way every decimal128 port mounts it. Nothing is copied
    /// into this repo and there is no test bundle involved, so the directory is
    /// resolved from this file's own path rather than from `Bundle.module`:
    /// tests run out of the build directory, but `#filePath` does not move.
    static let directory: URL = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent()  // Decimal128TextCodecTests
        .deletingLastPathComponent()  // Tests
        .deletingLastPathComponent()  // repo root
        .appendingPathComponent("resources/text_bid_dpd")

    /// One table, read off the filesystem.
    static func load(_ name: String) throws -> [CorpusRow] {
        let url = directory.appendingPathComponent("\(name).csv.txt")
        guard FileManager.default.fileExists(atPath: url.path) else {
            throw CorpusError.missing(name)
        }
        return try parse(String(contentsOf: url, encoding: .utf8), name)
    }

    private static func parse(_ contents: String, _ name: String) throws -> [CorpusRow] {
        var rows: [CorpusRow] = []
        for (index, rawLine) in contents.split(separator: "\n", omittingEmptySubsequences: false).enumerated() {
            var line = Substring(rawLine)
            while line.hasSuffix("\r") {
                line = line.dropLast()
            }
            line = skipSpace(line)
            if line.isEmpty || line.hasPrefix("#") {
                continue
            }

            let text: String
            if line.hasPrefix("\"") {
                (text, line) = readQuoted(line)
            } else {
                (text, line) = readField(line)
            }
            var bidHex = ""
            var dpdHex = ""
            var status = ""
            (bidHex, line) = readNextField(line)
            (dpdHex, line) = readNextField(line)
            (status, line) = readNextField(line)

            guard let bid = Hex.parse32(bidHex), let dpd = Hex.parse32(dpdHex) else {
                throw CorpusError.malformed(name, index + 1, bidHex, dpdHex)
            }
            rows.append(CorpusRow(text: text, bid: bid, dpd: dpd,
                                  status: status, lineNumber: index + 1))
        }
        return rows
    }

    // -- the reader, matching the C port's byte for byte ----------------------

    private static func skipSpace(_ s: Substring) -> Substring {
        var t = s
        while let c = t.first, c == " " || c == "\t" {
            t = t.dropFirst()
        }
        return t
    }

    /// One comma-delimited field, stopping at `,` or `#` or end of line, with
    /// surrounding whitespace trimmed.
    private static func readField(_ s: Substring) -> (String, Substring) {
        let start = skipSpace(s)
        var end = start
        while let c = end.first, c != ",", c != "#" {
            end = end.dropFirst()
        }
        var value = start[start.startIndex..<end.startIndex]
        while let c = value.last, c == " " || c == "\t" {
            value = value.dropLast()
        }
        return (String(value), end)
    }

    /// Step over a field separator, then read the next field. Yields the empty
    /// string when the row has no further column.
    private static func readNextField(_ s: Substring) -> (String, Substring) {
        var rest = skipSpace(s)
        guard rest.hasPrefix(",") else { return ("", rest) }
        rest = rest.dropFirst()
        return readField(rest)
    }

    /// The quoted text column, honouring `\\` and `\"` escapes.
    private static func readQuoted(_ s: Substring) -> (String, Substring) {
        var rest = s.dropFirst() // opening quote
        var out = ""
        while let c = rest.first, c != "\"" {
            rest = rest.dropFirst()
            var ch = c
            if ch == "\\", let next = rest.first {
                ch = next
                rest = rest.dropFirst()
            }
            out.append(ch)
        }
        if rest.hasPrefix("\"") {
            rest = rest.dropFirst()
        }
        return (out, rest)
    }
}

enum CorpusError: Error, CustomStringConvertible {
    case missing(String)
    case malformed(String, Int, String, String)

    var description: String {
        switch self {
        case .missing(let name):
            return """
                \(name).csv.txt is missing from \(Corpus.directory.path). \
                The decimal128-resources submodule is not checked out: run \
                `git submodule update --init --recursive`.
                """
        case .malformed(let name, let line, let bid, let dpd):
            return "\(name).csv.txt line \(line): malformed hex columns <\(bid)> <\(dpd)>"
        }
    }
}

// ---------------------------------------------------------------------------
// Thin wrappers so the tests read the way the codec's own API does.
// ---------------------------------------------------------------------------

func bidParse(_ text: String) -> (bits: UInt128, error: String?) {
    var bits: UInt128 = (UInt128(0xFEED) << 64) | UInt128(0xFACE)
    let err = Decimal128TextCodec.bid128Parse(&bits, text)
    return (bits, err)
}

func dpdParse(_ text: String) -> (bits: UInt128, error: String?) {
    var bits: UInt128 = (UInt128(0xFEED) << 64) | UInt128(0xFACE)
    let err = Decimal128TextCodec.dpd128Parse(&bits, text)
    return (bits, err)
}
